function _momoOBaseSet(k, ts){ try{ const m=_momoReadJson(_MOMO_OBASE_LS,{})||{}; m[k]=ts||0; localStorage.setItem(_MOMO_OBASE_LS,JSON.stringify(m)); }catch{} }
