window.__momoNoteOriginsCloudBase=function(k, ts){ if(ts) _momoOBaseSet(k, ts); }; // firebase.js 訂閱：接受雲端後記錄基準
window.__momoOriginsBaseGet=function(k){ return _momoOBaseGet(k); };              // 預覽：讀本機基準版本
