  const maxCovered=covered[covered.length-1], miss=new Set();
  (orderDates||[]).forEach(od=>{ const s=String(od||''); if(s.length>=6){ const mo=s.slice(0,4)+'-'+s.slice(4,6); if(mo>maxCovered) miss.add(mo); } });   // 只收 > 清單最後涵蓋月的新月份
